import{z as n,x as p,o as E,c as o,q as t,j as r,D as e,d as s,s as i,S as B}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"切断掩模","description":"","frontmatter":{"title":"切断掩模","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/cut-mask-dpt.md","filePath":"litho/cut-mask-dpt.md","lastUpdated":1791413859000}'),A={name:"litho/cut-mask-dpt.md"};function d(c,a,h,m,u,D){const l=p("Mermaid");return E(),o("div",null,[a[2]||(a[2]=t('<h1 id="切断掩模" tabindex="-1">切断掩模 <a class="header-anchor" href="#切断掩模" aria-label="Permalink to &quot;切断掩模&quot;">​</a></h1><div class="epigraph"><p>自对准线栅可以很长、很密；晶体管要的是有限长栅极。切断掩模在格点上把线打断，套刻从「对内半节距」回到切与线的对准。</p><footer>—— 据一维栅极 / gridded design 与 cut-mask 双重图形的工艺通称</footer></div><p><a href="/litho/odd-even-pitch">上一课</a>（奇偶节距）。把芯轴侧与间隙侧的奇偶误差钉成节距漂移。缺口是：spacer 留下的是连续（或成环）的线，器件要在指定位置终止。切断掩模（cut mask）用另一次光刻在允许的栅格上切。代价账留给<a href="/litho/duv-multipattern-cost">浸没多重图形成本</a>，本课只钉切与 1D 栅的几何。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SADP 擅长固定节距的长线。逻辑栅、鳍、某些金属轨道必须在单元边界或接触处断开。侧墙闭合环若不切，会在线端短路或无法定义栅长。切的位置是二次图形：切孔或切缝之间的间距若太密，单次切层又撞 \\(k_1\\)，于是切层自己也要 LELE 染色——「线自对准、切多重」。</p><p>缺口因此是「自对准线 + cut」，而不是再调 mandrel CD 去消 walking。Walking 让奇偶 space 不同，切在错误的 space 相位上还会碰到不同的线宽，但切的一阶问题仍是 overlay 与切层分解。</p><h3 id="切的是线-不是再做一次线层-lele" tabindex="-1">切的是线，不是再做一次线层 LELE <a class="header-anchor" href="#切的是线-不是再做一次线层-lele" aria-label="Permalink to &quot;切的是线，不是再做一次线层 LELE&quot;">​</a></h3><p>Cut 多边形的并集定义「哪里不要线」。对准对象是已存在的 spacer 线栅（或先切 mandrel 再长 spacer，切的对象变成芯轴）。套刻误差让切缝滑离目标：欠切则线连在一起，过切则切到邻线。这与 LELE 两套线之间的 \\(\\delta\\) 不同源：这里没有第二色线，只有切相对线。</p><p>切缝沿着线栅滑动时会发生什么？结局只有三种：没滑到位是短路，滑过头是切伤邻线，落在允许窗口内才得到想要的光栅长。切层套刻预算的全部意义，就是把「正好」那个窗口撑到足够宽。</p>',9)),(E(),r(B,null,{default:e(()=>[i(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20CUT%5B%22%E5%88%87%E7%BC%9D%E7%9B%B8%E5%AF%B9%E7%BA%BF%E6%A0%85%E5%B9%B3%E7%A7%BB%22%5D%20--%3E%20Q%7B%22%E5%88%87%E7%BC%9D%E8%90%BD%E7%82%B9%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%AC%A0%E5%88%87%EF%BC%9A%E6%B2%A1%E5%88%87%E9%80%8F%22%7C%20U%5B%22%E7%BA%BF%E7%AB%AF%E4%BB%8D%E7%9B%B8%E8%BF%9E%EF%BC%8C%E6%A0%85%E9%97%B4%E7%9F%AD%E8%B7%AF%22%5D%0A%20%20Q%20--%3E%7C%22%E8%90%BD%E5%9C%A8%E5%85%81%E8%AE%B8%E7%AA%97%E5%8F%A3%22%7C%20OK%5B%22%E7%BA%BF%E7%AB%AF%E6%AD%A3%E7%A1%AE%E5%AE%9A%E4%B9%89%EF%BC%8C%E6%A0%85%E9%95%BF%E5%90%88%E6%A0%BC%22%5D%0A%20%20Q%20--%3E%7C%22%E8%BF%87%E5%88%87%EF%BC%9A%E5%88%87%E8%BF%87%E5%A4%B4%22%7C%20O%5B%22%E4%BC%A4%E5%88%B0%E9%82%BB%E7%BA%BF%EF%BC%8C%E5%BC%80%E8%B7%AF%E6%88%96%E5%A4%B1%E6%95%88%22%5D%0A%20%20U%20--%3E%20FAIL%5B%22%E7%94%B5%E5%AD%A6%E5%A4%B1%E6%95%88%EF%BC%8C%E5%83%8F%E9%9A%8F%E6%9C%BA%E7%BC%BA%E9%99%B7%22%5D%0A%20%20O%20--%3E%20FAIL%0A%20%20OK%20--%3E%20GOOD%5B%22%E5%8D%95%E5%85%83%E5%8A%9F%E8%83%BD%E6%AD%A3%E5%B8%B8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p><span class="marginnote">直觉类比：切断掩模像裁缝下剪——SADP 先织出一匹节距均匀的「布」（连续线栅），cut 版是纸样，剪刀必须沿纸样剪断。剪刀歪了：没剪断，两根线连着（短路）；剪过头，把旁边一根好线剪伤（失效）。所以「剪」这件事也要留出歪几纳米仍合法的余量。</span></p><p><span class="marginnote">术语翻译：「后切」是先让 spacer 转印出完整长线、再用一次光刻剪断，线端形状由切缝决定；「先切」是先在 mandrel 骨架上开缺口、再长 spacer，线端形状由骨架缺口决定。两者的套刻对象不同——一个对已成的线，一个对芯轴——规则书要分开写。</span></p><p><span class="marginnote">常见误区：初学者容易把「线自对准」读成「省曝光、所以便宜」。实际账是：线层或许一次 mandrel 就成，但 cut 层自己要一次甚至两次曝光（切过密时染色），外加专用掩模与切后计量。省下的和吃回去的要在模块级结账，单看一层都会算错方向。</span></p><p><span class="marginnote">1D 栅极工艺把标准单元轨道和切位置限制在格点上，正是为了让 cut 可印、可着色。任意二维线端不是本课的友好对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>后切：先完成 mandrel + spacer 转印成线，再涂胶曝光切缝，刻蚀打断。先切：在 mandrel 上切出缺口再长 spacer，线端形状由芯轴缺口决定，套刻对象是芯轴。两种都要 OPC；切缝往往是孔或短缝，照明与线层偶极完全不同，不能共用栅极光瞳。</p><p>切太密则对切层做颜色分解：两次切曝光，套刻进入两张切版之间以及切与线之间。公开 1D 流程里「线一层 SADP + 切两层 DPT」是常见句子，不是每个厂的掩模张数表。</p><h3 id="设计规则-在哪切" tabindex="-1">设计规则：在哪切 <a class="header-anchor" href="#设计规则-在哪切" aria-label="Permalink to &quot;设计规则：在哪切&quot;">​</a></h3><p>合法切位置、最小切–切间距、切相对线端的伸出（keep-out），构成单元库的格子。布线若在非格点停线，不是 OPC 能救的。这与 LELE 金属的可染色性同类：都是把设计空间卖给可制造性。</p>',9)),(E(),r(B,null,{default:e(()=>[i(l,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20LN%5B%22SADP%20%E7%BA%BF%E6%A0%85%22%5D%20--%3E%20CUT%5B%22%E5%88%87%E6%96%AD%E5%85%89%E5%88%BB%22%5D%0A%20%20CUT%20--%3E%20END%5B%22%E6%9C%89%E9%99%90%E9%95%BF%E6%A0%85%20%2F%20%E7%BA%BF%E7%AB%AF%22%5D%0A%20%20CUT%20--%3E%20OV%5B%22%E5%88%87%E7%9B%B8%E5%AF%B9%E7%BA%BF%E7%9A%84%E5%A5%97%E5%88%BB%22%5D%0A%20%20DENSE%5B%22%E5%88%87%E7%BC%9D%E8%BF%87%E5%AF%86%22%5D%20--%3E%20C2%5B%22%E5%88%87%E5%B1%82%E5%86%8D%E6%9F%93%E8%89%B2%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学上切层是另一张掩模的空中像，通常 \\(k_1\\) 比 mandrel 舒适，但二维孔、线端缩短、切缝圆化会让电学栅长漂。套刻：扫描机 overlay 加掩模 PPE，把切缝中心相对线栅平移。Pitch walking 使相邻 space 不等，切缝若按理想等节距摆，会系统靠近某一种 space 的线，桥接风险不对称——所以切层 OPC 有时要感知奇偶。</p><p>产能：线层可能一次 mandrel，切层一次或两次，仍少于同等密度的全 LELE 线，但多了切专用掩模与刻蚀。不要只用「自对准所以少曝光」来结账。</p><p>切缝的空中像是孔类或短缝，<a href="/litho/sraf-assist">SRAF</a> 与孔照明（环带或四极）往往比线层偶极更合适。把栅极偶极抄到 cut，稀疏切孔的旁瓣和焦深会先爆。这是「一层一个光瞳」在多重图形里的具体例子。</p><p><span class="marginnote">切偏造成的短路/开路在电性上像缺陷，计量要用切后 CD-SEM 或电压衬度，而不是只看 walking 分桶。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 EUV 单次切层写成已经取消所有 cut DPT：是否一张 EUV 切得下，看切密度与孔 \\(k_1\\)，各厂不同。也不把 fin cut、gate cut、metal cut 当成同一张版——对准层级不同。这些张数乘进 7/5 nm 代价的账，留给后面的<a href="/litho/duv-multipattern-cost">浸没多重图形成本</a>一课；本课禁止编 wph 与良率。</p><p>EUV 当 mandrel、DUV 当切（或反过来）是混跑策略，属于更后的混合课。这里只要求：有自对准线，就几乎一定有 cut 这种二次图形。</p><p><span class="marginnote">环状 spacer 的「不需要的边」有时用 block / keep 掩模大面积去掉，而不是细切。Block 与 cut 都是二次图形，规则与照明不同，合同上不要混名。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>切断掩模把 spacer 长线变成有限长 1D 栅极图形。</li><li>套刻是切相对线（及切与切），不是成对 spacer 的线层 \\(\\delta\\)。</li><li>切过密则切层自己要染色。</li><li>设计必须格点化；walking 会让切桥接风险不对称。</li><li>多重曝光的成本结构下一课。</li><li>出处：1D 栅极 / cut-mask 工艺通称；SADP 公开流程中的 cut 模块。</li></ul>',11))])}const F=n(A,[["render",d]]);export{_ as __pageData,F as default};
